-- MediScript Clinic System — Full Schema
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE TABLE IF NOT EXISTS doctors (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), name VARCHAR(200) NOT NULL, speciality VARCHAR(100), license_no VARCHAR(50) UNIQUE, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS patients (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), name VARCHAR(200) NOT NULL, date_of_birth DATE, gender VARCHAR(10), phone VARCHAR(20), email VARCHAR(100), created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS visits (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), patient_id UUID NOT NULL REFERENCES patients(id) ON DELETE CASCADE, doctor_id UUID NOT NULL REFERENCES doctors(id), raw_input TEXT, visit_date TIMESTAMPTZ DEFAULT NOW(), status VARCHAR(20) DEFAULT 'draft', created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS prescriptions (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), visit_id UUID NOT NULL REFERENCES visits(id) ON DELETE CASCADE, drug_name VARCHAR(200) NOT NULL, dosage VARCHAR(100), frequency VARCHAR(100), duration VARCHAR(100), route VARCHAR(50), notes TEXT, unit_price DECIMAL(10,2) DEFAULT 0, quantity INT DEFAULT 1, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS lab_tests (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), visit_id UUID NOT NULL REFERENCES visits(id) ON DELETE CASCADE, test_name VARCHAR(200) NOT NULL, test_code VARCHAR(50), priority VARCHAR(20) DEFAULT 'routine', notes TEXT, price DECIMAL(10,2) DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS clinical_notes (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), visit_id UUID NOT NULL REFERENCES visits(id) ON DELETE CASCADE, category VARCHAR(50) NOT NULL, content TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bills (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), visit_id UUID NOT NULL UNIQUE REFERENCES visits(id) ON DELETE CASCADE, consultation_fee DECIMAL(10,2) DEFAULT 0, drug_total DECIMAL(10,2) DEFAULT 0, lab_total DECIMAL(10,2) DEFAULT 0, other_charges DECIMAL(10,2) DEFAULT 0, discount DECIMAL(10,2) DEFAULT 0, tax_amount DECIMAL(10,2) DEFAULT 0, total_amount DECIMAL(10,2) DEFAULT 0, status VARCHAR(20) DEFAULT 'pending', created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bill_items (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), bill_id UUID NOT NULL REFERENCES bills(id) ON DELETE CASCADE, category VARCHAR(50) NOT NULL, description VARCHAR(300) NOT NULL, quantity INT DEFAULT 1, unit_price DECIMAL(10,2) DEFAULT 0, total DECIMAL(10,2) DEFAULT 0);
CREATE TABLE IF NOT EXISTS drug_catalog (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), name VARCHAR(200) NOT NULL, generic_name VARCHAR(200), unit_price DECIMAL(10,2) DEFAULT 0, category VARCHAR(100));
CREATE TABLE IF NOT EXISTS test_catalog (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), test_name VARCHAR(200) NOT NULL, test_code VARCHAR(50) UNIQUE, price DECIMAL(10,2) DEFAULT 0, category VARCHAR(100));
CREATE INDEX IF NOT EXISTS idx_visits_patient ON visits(patient_id);
CREATE INDEX IF NOT EXISTS idx_visits_status ON visits(status);
